SET state = #{state}, end_time = #{endTime}, duration_ms = #{durationMs},
    read_records = #{readRecords}, write_records = #{writeRecords}, error_records = #{errorRecords},
    read_bytes = #{readBytes}, speed_record = #{speedRecord}, speed_byte = #{speedByte},
    message = #{message}, log_file = #{logFile}
WHERE id = #{id}

